from collections.abc import Sequence
from pathlib import Path

import pytest
from plugin_fakes import FakeOrchestrator, FakeWarehouse, install_distribution, register

from datapatchbay.generate import GenerationError, generate_repo
from datapatchbay.plugins import DataProductPlan, SqlTask, TablePlan

SA_DAG = '''\
# Generated by datapatchbay from dataproducts/sa_ilab_orders/dataproduct.yaml. Do not edit: `dpb generate` overwrites this file.

import importlib.util
from datetime import datetime
from pathlib import Path

from airflow.sdk import Asset, DAG, task


DATAPRODUCT_DIR = (Path(__file__).resolve().parent / "../dataproducts/sa_ilab_orders").resolve()


def _build_task(task_id, path, function, params):
    """Create a task that loads a file of the data product and calls a function in it."""

    @task(task_id=task_id)
    def build():
        spec = importlib.util.spec_from_file_location(f"patchbay_{task_id}", DATAPRODUCT_DIR / path)
        if spec is None or spec.loader is None:
            raise ImportError(f"cannot load {path}")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        getattr(module, function)(**params)

    return build()


with DAG(
    dag_id="sa_ilab_orders",
    schedule="0 5 * * *",
    start_date=datetime(2025, 1, 1),
    catchup=False,
    default_args={"owner": "Jane Doe"},
    tags=["patchbay"],
):
    build_ingested_orders = _build_task("build_ingested_orders", "src/ingested.py", "build", {"limit": 100})
    build_orders = _build_task("build_orders", "src/orders.py", "build", {})
    build_ingested_orders >> build_orders

    @task(task_id="publish_outputs", outlets=[Asset(name="sa_ilab_orders", uri="x-patchbay://sa_ilab_orders")])
    def publish_outputs():
        """Mark the output ports as updated; Airflow does so when this task succeeds."""

    publish = publish_outputs()
    build_orders >> publish
'''

AGG_SCHEDULE_AND_OUTLETS = """\
with DAG(
    dag_id="agg_lab_turnaround",
    schedule=[Asset(name="sa_ilab_orders", uri="x-patchbay://sa_ilab_orders")],
"""


def generated(repo: Path, name: str, directory: str = "generated") -> str:
    return (repo / directory / name).read_text()


def test_generate_writes_one_dag_file_per_data_product_into_the_output_dir_setting(lab_repo: Path):
    result = generate_repo(lab_repo)
    assert result.report.ok
    assert [str(path) for path in result.files] == ["agg_lab_turnaround.py", "agg_lab_weekly.py", "sa_ilab_orders.py"]
    assert sorted(path.name for path in (lab_repo / "generated").iterdir()) == [
        "agg_lab_turnaround.py",
        "agg_lab_weekly.py",
        "sa_ilab_orders.py",
    ]


class NoSqlWarehouse:
    """A warehouse that adds no tasks, so the DAG shows only builds and the publish task."""

    def apply_tasks(self, dataproduct: DataProductPlan) -> Sequence[SqlTask]:
        return ()

    def audit_tasks(self, table: TablePlan) -> Sequence[SqlTask]:
        return ()


def test_generate_writes_the_complete_dag_for_a_source_fed_data_product(
    lab_repo: Path, monkeypatch: pytest.MonkeyPatch
):
    register(monkeypatch, "warehouse", "nosql", NoSqlWarehouse)
    (lab_repo / "datapatchbay.yaml").write_text("schema_version: 1\nwarehouse: nosql\n")
    generate_repo(lab_repo)
    assert generated(lab_repo, "sa_ilab_orders.py") == SA_DAG


def test_generate_honours_the_output_dir_setting_and_the_override(lab_repo: Path, tmp_path: Path):
    (lab_repo / "datapatchbay.yaml").write_text("schema_version: 1\noutput_dir: build/dags\n")
    generate_repo(lab_repo)
    assert (lab_repo / "build/dags/sa_ilab_orders.py").is_file()

    elsewhere = tmp_path / "elsewhere"
    result = generate_repo(lab_repo, output_dir=elsewhere)
    assert result.output_dir == elsewhere.resolve()
    assert (elsewhere / "sa_ilab_orders.py").is_file()
    # The data product folder is found from the file, so the path follows the output folder.
    assert '/ "../repo/dataproducts/sa_ilab_orders"' in (elsewhere / "sa_ilab_orders.py").read_text()


def test_generated_files_do_not_mention_datapatchbay_outside_the_header_comment(lab_repo: Path):
    generate_repo(lab_repo)
    files = list((lab_repo / "generated").iterdir())
    assert files
    for path in files:
        code = "\n".join(line for line in path.read_text().splitlines() if not line.startswith("#"))
        assert "datapatchbay" not in code
        assert "dpb" not in code


def test_a_data_product_that_reads_another_runs_when_its_output_port_is_updated(lab_repo: Path):
    generate_repo(lab_repo)
    text = generated(lab_repo, "agg_lab_turnaround.py")
    assert AGG_SCHEDULE_AND_OUTLETS in text
    assert 'outlets=[Asset(name="agg_lab_turnaround", uri="x-patchbay://agg_lab_turnaround")]' in text


def test_a_data_product_with_a_source_and_a_read_runs_on_the_schedule_and_when_the_assets_are_updated(lab_repo: Path):
    # Airflow's AssetAndTimeSchedule would wait for both; the data product must run on either.
    generate_repo(lab_repo)
    text = generated(lab_repo, "agg_lab_weekly.py")
    assert (
        '    schedule=AssetOrTimeSchedule(timetable=CronTriggerTimetable("30 6 * * 1", timezone="UTC"), '
        'assets=[Asset(name="sa_ilab_orders", uri="x-patchbay://sa_ilab_orders")]),\n'
    ) in text
    assert "from airflow.sdk import Asset, AssetOrTimeSchedule, CronTriggerTimetable, DAG, task" in text
    assert "AssetAndTimeSchedule" not in text


def test_a_data_product_without_inputs_has_no_schedule(lab_repo: Path):
    product = lab_repo / "dataproducts/agg_lab_turnaround/dataproduct.yaml"
    product.write_text(product.read_text().replace("inputs: [sa_ilab_orders]", "inputs: []"))
    (lab_repo / "dataproducts/agg_lab_turnaround/inputs/sa_ilab_orders/port.yaml").unlink()
    (lab_repo / "dataproducts/agg_lab_turnaround/inputs/sa_ilab_orders").rmdir()
    assert generate_repo(lab_repo).report.ok
    assert "    schedule=None,\n" in generated(lab_repo, "agg_lab_turnaround.py")


def test_the_same_input_gives_byte_identical_output(lab_repo: Path, tmp_path: Path):
    generate_repo(lab_repo, output_dir=tmp_path / "one")
    generate_repo(lab_repo, output_dir=tmp_path / "two")
    for name in ("agg_lab_turnaround.py", "agg_lab_weekly.py", "sa_ilab_orders.py"):
        assert (tmp_path / "one" / name).read_bytes() == (tmp_path / "two" / name).read_bytes()


def test_the_build_task_order_follows_needs_whatever_the_file_order(lab_repo: Path):
    # `orders` is listed before `ingested_orders` on disk (output ports sort after input ports) but needs it.
    generate_repo(lab_repo)
    text = generated(lab_repo, "sa_ilab_orders.py")
    assert text.index("build_ingested_orders = ") < text.index("build_orders = ")
    assert "    build_ingested_orders >> build_orders\n" in text


def test_params_are_written_as_plain_literals(lab_repo: Path):
    table = lab_repo / "dataproducts/sa_ilab_orders/inputs/sa_ilab_orders_private/ingested.yaml"
    table.write_text(
        table.read_text().replace(
            "    limit: 100\n", '    limit: 100\n    ratio: 0.5\n    flag: true\n    tags: [a, "b c"]\n    none: null\n'
        )
    )
    generate_repo(lab_repo)
    expected = '{"limit": 100, "ratio": 0.5, "flag": True, "tags": ["a", "b c"], "none": None}'
    assert expected in generated(lab_repo, "sa_ilab_orders.py")


def test_a_param_that_is_not_a_plain_value_names_the_data_product_and_table_and_writes_nothing(lab_repo: Path):
    table = lab_repo / "dataproducts/sa_ilab_orders/outputs/sa_ilab_orders/orders.yaml"
    table.write_text(table.read_text().replace("  needs:", "  params:\n    since: 2025-01-01\n  needs:"))
    with pytest.raises(GenerationError, match=r"data product 'sa_ilab_orders': table 'orders': .*date"):
        generate_repo(lab_repo)
    assert not (lab_repo / "generated").exists()


def test_generate_writes_nothing_when_the_repo_is_invalid(lab_repo: Path):
    (lab_repo / "dataproducts/sa_ilab_orders/src/orders.py").unlink()
    result = generate_repo(lab_repo)
    assert not result.report.ok
    assert "does not exist" in result.report.problems[0].message
    assert result.files == ()
    assert not (lab_repo / "generated").exists()


def test_source_input_ports_with_different_schedules_cannot_share_one_dag(lab_repo: Path):
    port = lab_repo / "dataproducts/sa_ilab_orders/inputs/sa_ilab_orders_extra/port.yaml"
    port.parent.mkdir(parents=True)
    port.write_text('schema_version: 1\nkind: schema\nsource: ilab\nschedule: "30 6 * * *"\n')
    product = lab_repo / "dataproducts/sa_ilab_orders/dataproduct.yaml"
    product.write_text(
        product.read_text().replace("[sa_ilab_orders_private]", "[sa_ilab_orders_private, sa_ilab_orders_extra]")
    )
    with pytest.raises(GenerationError, match="data product 'sa_ilab_orders': the source input ports have different"):
        generate_repo(lab_repo)
    assert not (lab_repo / "generated").exists()


def test_a_fake_orchestrator_plugin_registered_through_entry_points_generates_instead_of_airflow(
    lab_repo: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
):
    install_distribution(monkeypatch, tmp_path / "site", "orchestrator", "fake", "plugin_fakes:FakeOrchestrator")
    (lab_repo / "datapatchbay.yaml").write_text("schema_version: 1\norchestrator: fake\n")
    result = generate_repo(lab_repo)
    assert [str(path) for path in result.files] == [
        "agg_lab_turnaround.txt",
        "agg_lab_weekly.txt",
        "sa_ilab_orders.txt",
    ]
    assert generated(lab_repo, "sa_ilab_orders.txt") == "sa_ilab_orders: ingested_orders,orders\n"
    assert generated(lab_repo, "agg_lab_weekly.txt") == "agg_lab_weekly: weekly_raw,weekly,weekly_pod\n"


def test_an_orchestrator_set_on_one_data_product_applies_to_that_data_product_only(
    lab_repo: Path, monkeypatch: pytest.MonkeyPatch
):
    register(monkeypatch, "orchestrator", "fake", FakeOrchestrator)
    product = lab_repo / "dataproducts/agg_lab_turnaround/dataproduct.yaml"
    product.write_text(product.read_text() + "orchestrator: fake\n")
    result = generate_repo(lab_repo)
    assert [str(path) for path in result.files] == ["agg_lab_turnaround.txt", "agg_lab_weekly.py", "sa_ilab_orders.py"]


def test_a_warehouse_plugin_adds_audit_and_apply_tasks_that_run_through_the_connection(
    lab_repo: Path, monkeypatch: pytest.MonkeyPatch
):
    register(monkeypatch, "warehouse", "fake", FakeWarehouse)
    (lab_repo / "datapatchbay.yaml").write_text("schema_version: 1\nwarehouse: fake\nconnection: dwh\n")
    generate_repo(lab_repo)
    text = generated(lab_repo, "sa_ilab_orders.py")
    assert "from airflow.providers.common.sql.operators.sql import SQLExecuteQueryOperator\n" in text
    body = text[text.index("with DAG(") :]
    assert body.split("tags=")[1] == (
        '["patchbay"],\n'
        "):\n"
        '    build_ingested_orders = _build_task("build_ingested_orders", "src/ingested.py", "build", {"limit": 100})\n'
        "    audit_ingested_orders = SQLExecuteQueryOperator(\n"
        '        task_id="audit_ingested_orders",\n'
        '        conn_id="dwh",\n'
        "        sql=\"SELECT 'it''s' FROM ingested_orders WHERE false\",\n"
        "    )\n"
        "    build_ingested_orders >> audit_ingested_orders\n"
        '    build_orders = _build_task("build_orders", "src/orders.py", "build", {})\n'
        "    audit_orders = SQLExecuteQueryOperator(\n"
        '        task_id="audit_orders",\n'
        '        conn_id="dwh",\n'
        "        sql=\"SELECT 'it''s' FROM orders WHERE false\",\n"
        "    )\n"
        "    build_orders >> audit_orders\n"
        "    audit_ingested_orders >> build_orders\n"
        "    apply_grants = SQLExecuteQueryOperator(\n"
        '        task_id="apply_grants",\n'
        '        conn_id="dwh",\n'
        '        sql="GRANT USAGE ON SCHEMA sa_ilab_orders TO reader;",\n'
        "    )\n"
        "    audit_orders >> apply_grants\n"
        "\n"
        '    @task(task_id="publish_outputs", outlets=[Asset(name="sa_ilab_orders", uri="x-patchbay://sa_ilab_orders")])\n'
        "    def publish_outputs():\n"
        '        """Mark the output ports as updated; Airflow does so when this task succeeds."""\n'
        "\n"
        "    publish = publish_outputs()\n"
        "    apply_grants >> publish\n"
    )


def test_the_postgres_warehouse_ends_each_dag_with_a_task_that_applies_the_access_through_the_connection(
    lab_repo: Path,
):
    (lab_repo / "datapatchbay.yaml").write_text("schema_version: 1\nconnection: dwh\n")
    generate_repo(lab_repo)
    body = generated(lab_repo, "sa_ilab_orders.py")
    body = body[body.index("with DAG(") :]
    assert (
        '        task_id="apply_access",\n        conn_id="dwh",\n        sql="-- Output port sa_ilab_orders\\n' in body
    )
    assert body.index("apply_access") < body.index("publish_outputs")
    assert "    build_orders >> apply_access\n" in body
    assert body.endswith("    apply_access >> publish\n")


def test_docker_and_kubernetes_tables_sit_in_one_dag_with_other_runtimes(lab_repo: Path):
    ingested = lab_repo / "dataproducts/sa_ilab_orders/inputs/sa_ilab_orders_private/ingested.yaml"
    ingested.write_text(ingested.read_text().replace("build:\n", "build:\n  runtime: docker\n  image: lab:1\n"))
    orders = lab_repo / "dataproducts/sa_ilab_orders/outputs/sa_ilab_orders/orders.yaml"
    orders.write_text(
        orders.read_text().replace(
            "build:\n", "build:\n  runtime: kubernetes\n  image: lab:2\n  container: {namespace: data}\n"
        )
    )
    generate_repo(lab_repo)
    dag = (lab_repo / "generated/sa_ilab_orders.py").read_text()
    assert "build_ingested_orders = DockerOperator(" in dag
    assert "build_orders = KubernetesPodOperator(" in dag
    assert 'namespace="data"' in dag
    assert "build_ingested_orders >> build_orders" in dag
